settings.liquid:
{%- assign gw_lang = request.locale.iso_code -%}

{%- case gw_lang -%}
  {%- when 'fr' -%}
    {%- assign gw_t1 = 'Livraison gratuite' -%}
    {%- assign gw_t2 = 'Bijoux garantis à vie' -%}
    {%- assign gw_t3 = 'Support 7j/7' -%}
    {%- assign gw_t4 = 'Paiement sécurisé' -%}
  {%- when 'de' -%}
    {%- assign gw_t1 = 'Kostenloser Versand' -%}
    {%- assign gw_t2 = 'Schmuck mit lebenslanger Garantie' -%}
    {%- assign gw_t3 = '7 Tage die Woche Support' -%}
    {%- assign gw_t4 = 'Sichere Zahlung' -%}
  {%- when 'es' -%}
    {%- assign gw_t1 = 'Envío gratis' -%}
    {%- assign gw_t2 = 'Joyas garantizadas de por vida' -%}
    {%- assign gw_t3 = 'Soporte 7 días a la semana' -%}
    {%- assign gw_t4 = 'Pago seguro' -%}
  {%- when 'it' -%}
    {%- assign gw_t1 = 'Spedizione gratuita' -%}
    {%- assign gw_t2 = 'Gioielli garantiti a vita' -%}
    {%- assign gw_t3 = 'Assistenza 7 giorni su 7' -%}
    {%- assign gw_t4 = 'Pagamento sicuro' -%}
  {%- else -%}
    {%- assign gw_t1 = 'Free shipping' -%}
    {%- assign gw_t2 = 'Jewelry guaranteed for life' -%}
    {%- assign gw_t3 = '7-day support' -%}
    {%- assign gw_t4 = 'Secure payment' -%}
{%- endcase -%}

<div class="gw-trust-badges">
  <div class="gw-badge">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="1" y="6" width="14" height="10"></rect><path d="M15 9h4l3 3v4h-7z"></path><circle cx="6" cy="18" r="1.6"></circle><circle cx="17" cy="18" r="1.6"></circle></svg>
    <span>{{ gw_t1 }}</span>
  </div>
  <div class="gw-badge">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2l7 3v6c0 5-3.5 8.5-7 10-3.5-1.5-7-5-7-10V5z"></path><path d="M9 12l2 2 4-4"></path></svg>
    <span>{{ gw_t2 }}</span>
  </div>
  <div class="gw-badge">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 13a9 9 0 0 1 18 0"></path><path d="M21 13v4a2 2 0 0 1-2 2h-1"></path><rect x="17" y="13" width="4" height="6" rx="1.5"></rect><rect x="3" y="13" width="4" height="6" rx="1.5"></rect></svg>
    <span>{{ gw_t3 }}</span>
  </div>
  <div class="gw-badge">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="10" width="16" height="10" rx="2"></rect><path d="M8 10V7a4 4 0 0 1 8 0v3"></path></svg>
    <span>{{ gw_t4 }}</span>
  </div>
</div>

<style>
  .gw-trust-badges {
    --gw-badge-bg: #F8ECEE;
    --gw-badge-border: #D8A8AF;
    --gw-badge-text: #5C1A2B;
    --gw-badge-icon: #5C1A2B;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 10px;
    margin: 18px 0;
  }
  .gw-trust-badges .gw-badge {
    display: flex;
    align-items: center;
    gap: 7px;
    background: var(--gw-badge-bg);
    border: 1px solid var(--gw-badge-border);
    border-radius: 999px;
    padding: 8px 16px;
    font-size: 14px;
    font-weight: 500;
    line-height: 1.2;
    color: var(--gw-badge-text);
    white-space: nowrap;
  }
  .gw-trust-badges .gw-badge svg {
    width: 19px;
    height: 19px;
    flex-shrink: 0;
    color: var(--gw-badge-icon);
  }
  @media (max-width: 480px) {
    .gw-trust-badges {
      gap: 8px;
    }
    .gw-trust-badges .gw-badge {
      font-size: 11.5px;
      padding: 7px 12px;
    }
    .gw-trust-badges .gw-badge svg {
      width: 17px;
      height: 17px;
    }
  }
</style>
